config.jsonSchemaText:
{
  "title": "Order validation result",
  "type": "object",
  "additionalProperties": false,
  "required": [
    "verdict",
    "reasoning",
    "confidence",
    "field_results",
    "skill_results",
    "pricing_adjustments"
  ],
  "properties": {
    "verdict": {
      "type": "string",
      "enum": [
        "pass",
        "flag"
      ],
      "description": "Overall outcome of the validation."
    },
    "reasoning": {
      "type": "string",
      "description": "Brief overall assessment, including missing inputs, blocked checks, and reference-data or scope limitations."
    },
    "confidence": {
      "type": "number",
      "minimum": 0,
      "maximum": 1,
      "description": "Confidence in the assessment from 0.0 to 1.0; not a compliance score."
    },
    "field_results": {
      "type": "array",
      "description": "One entry per distinct input path that was checked.",
      "items": {
        "type": "object",
        "additionalProperties": false,
        "required": [
          "field",
          "status",
          "reason"
        ],
        "properties": {
          "field": {
            "type": "string",
            "description": "Input field path, for example /lines/0/sku."
          },
          "status": {
            "type": "string",
            "enum": [
              "pass",
              "flag"
            ]
          },
          "reason": {
            "type": "string",
            "description": "Combined reasons of all checks on this field, naming the responsible skill."
          }
        }
      }
    },
    "skill_results": {
      "type": "array",
      "description": "Exactly one entry per skill.",
      "items": {
        "type": "object",
        "additionalProperties": false,
        "required": [
          "skill",
          "status",
          "reason"
        ],
        "properties": {
          "skill": {
            "type": "string",
            "enum": [
              "validate-order-product-identity",
              "validate-order-product-availability",
              "evaluate-order-discounts-promotions"
            ]
          },
          "status": {
            "type": "string",
            "enum": [
              "pass",
              "flag",
              "blocked"
            ],
            "description": "flag: a violation was found; blocked: a mandatory check could not be completed."
          },
          "reason": {
            "type": "string",
            "description": "Why the skill passed, flagged or was blocked."
          }
        }
      }
    },
    "pricing_adjustments": {
      "type": "object",
      "additionalProperties": false,
      "description": "Proposed price adjustments from the discounts and promotions skill; never applied to the order.",
      "required": [
        "proposed_only",
        "currency",
        "original_merchandise_subtotal",
        "discount_total",
        "adjusted_merchandise_subtotal",
        "proposed_order_total",
        "line_adjustments"
      ],
      "properties": {
        "proposed_only": {
          "type": "boolean",
          "enum": [
            true
          ]
        },
        "currency": {
          "type": "string",
          "description": "Currency code; empty string when unknown or unsupported."
        },
        "original_merchandise_subtotal": {
          "type": "string",
          "description": "Two-decimal amount; empty string when incomplete or unassessable."
        },
        "discount_total": {
          "type": "string",
          "description": "Two-decimal amount; empty string when incomplete or unassessable."
        },
        "adjusted_merchandise_subtotal": {
          "type": "string",
          "description": "Two-decimal amount; empty string when incomplete or unassessable."
        },
        "proposed_order_total": {
          "type": "string",
          "description": "Two-decimal final payable including confirmed tax and shipping; otherwise empty string."
        },
        "line_adjustments": {
          "type": "array",
          "description": "One entry per priced order line.",
          "items": {
            "type": "object",
            "additionalProperties": false,
            "required": [
              "line_id",
              "promotion_id",
              "discount_percent",
              "gross_amount",
              "discount_amount",
              "adjusted_amount"
            ],
            "properties": {
              "line_id": {
                "type": "string",
                "description": "Identifier of the order line in the input."
              },
              "promotion_id": {
                "type": "string",
                "description": "Applied promotion ID; empty string when no offer applies."
              },
              "discount_percent": {
                "type": "number",
                "minimum": 0,
                "maximum": 100
              },
              "gross_amount": {
                "type": "string",
                "description": "Two-decimal amount."
              },
              "discount_amount": {
                "type": "string",
                "description": "Two-decimal amount."
              },
              "adjusted_amount": {
                "type": "string",
                "description": "Two-decimal amount."
              }
            }
          }
        }
      }
    }
  }
}

